// Line bundles and divisors on the projective plane -- the same check as the Python, in Rust.
// No crates.  Three roads to one answer, Pic(P^2) = Z, generated by a line L:
//   road 1: divisors by exact degree arithmetic; a degree-0 divisor is div of a ratio of forms
//   road 2: the gluing data of O(D), and its first Chern class as a winding number
//   road 3: Bezout, (2h)(3h) = 6, by elimination and by a parametrised circle, both exact
use std::f64::consts::PI;

#[derive(Clone, Copy, PartialEq, Debug)]
struct Fr { n: i128, d: i128 }                       // a fraction in lowest terms, d > 0
fn gcd(a: i128, b: i128) -> i128 { if b == 0 { a.abs() } else { gcd(b, a % b) } }
fn fr(n: i128, d: i128) -> Fr { let g = gcd(n, d).max(1); let s = if d < 0 { -1 } else { 1 }; Fr { n: s * n / g, d: s * d / g } }
fn add(a: Fr, b: Fr) -> Fr { fr(a.n.checked_mul(b.d).unwrap() + b.n.checked_mul(a.d).unwrap(), a.d.checked_mul(b.d).unwrap()) }
fn mul(a: Fr, b: Fr) -> Fr { fr(a.n.checked_mul(b.n).unwrap(), a.d.checked_mul(b.d).unwrap()) }
fn div(a: Fr, b: Fr) -> Fr { fr(a.n.checked_mul(b.d).unwrap(), a.d.checked_mul(b.n).unwrap()) }
fn fs(a: Fr) -> String { if a.d == 1 { format!("{}", a.n) } else { format!("{}/{}", a.n, a.d) } }
const Z0: Fr = Fr { n: 0, d: 1 };

#[derive(Clone, Copy)]
struct Cx { re: f64, im: f64 }
fn cm(a: Cx, b: Cx) -> Cx { Cx { re: a.re * b.re - a.im * b.im, im: a.re * b.im + a.im * b.re } }
fn cd(a: Cx, b: Cx) -> Cx { let m = b.re * b.re + b.im * b.im; Cx { re: (a.re * b.re + a.im * b.im) / m, im: (a.im * b.re - a.re * b.im) / m } }
fn ca(a: Cx, b: Cx) -> Cx { Cx { re: a.re + b.re, im: a.im + b.im } }
fn cr(x: f64) -> Cx { Cx { re: x, im: 0.0 } }
fn csqrt(a: Cx) -> Cx { let (r, t) = ((a.re * a.re + a.im * a.im).sqrt().sqrt(), a.im.atan2(a.re) / 2.0); Cx { re: r * t.cos(), im: r * t.sin() } }
fn cabs(a: Cx) -> f64 { (a.re * a.re + a.im * a.im).sqrt() }

type Form = Vec<((u32, u32, u32), i128)>;
fn ev(f: &Form, p: (i128, i128, i128)) -> i128 { f.iter().map(|&((a, b, e), c)| c * p.0.pow(a) * p.1.pow(b) * p.2.pow(e)).sum() }
fn evc(f: &Form, p: [Cx; 3]) -> Cx {
    f.iter().fold(cr(0.0), |s, &((a, b, e), c)| {
        let mut t = cr(c as f64);
        for (k, z) in [(a, p[0]), (b, p[1]), (e, p[2])] { for _ in 0..k { t = cm(t, z) } }
        ca(s, t) })
}
fn deg(f: &Form) -> u32 { let d = f[0].0.0 + f[0].0.1 + f[0].0.2; assert!(f.iter().all(|m| m.0.0 + m.0.1 + m.0.2 == d)); d }
fn pmul(p: &Vec<Fr>, q: &Vec<Fr>) -> Vec<Fr> {
    let mut r = vec![Z0; p.len() + q.len() - 1];
    for (i, &a) in p.iter().enumerate() { for (j, &b) in q.iter().enumerate() { r[i + j] = add(r[i + j], mul(a, b)) } }
    r
}
fn comp(f: &Form, xyz: [&Vec<Fr>; 3]) -> Vec<Fr> {
    let mut out = vec![Z0];
    for &((a, b, e), c) in f {
        let mut t = vec![fr(c, 1)];
        for (poly, k) in [(xyz[0], a), (xyz[1], b), (xyz[2], e)] { for _ in 0..k { t = pmul(&t, poly) } }
        let n = out.len().max(t.len());
        out = (0..n).map(|i| add(*out.get(i).unwrap_or(&Z0), *t.get(i).unwrap_or(&Z0))).collect();
    }
    while out.len() > 1 && *out.last().unwrap() == Z0 { out.pop(); }
    out
}
fn divide(p: &Vec<Fr>, r: Fr) -> (Vec<Fr>, Fr) {
    let mut q = vec![]; let mut acc = Z0;
    for &c in p.iter().rev() { acc = add(mul(acc, r), c); q.push(acc) }
    let rem = q.pop().unwrap(); q.reverse(); (q, rem)
}
fn show(p: &Vec<Fr>, v: &str) -> String {
    let mut out = String::new();
    for k in (0..p.len()).rev() {
        let c = p[k];
        if c == Z0 { continue }
        let s = if c.n < 0 { "-" } else if out.is_empty() { "" } else { "+" };
        out += &(if out.is_empty() { s.to_string() } else { format!(" {} ", s) });
        let a = Fr { n: c.n.abs(), d: c.d };
        if !(a == fr(1, 1) && k > 0) { out += &fs(a) }
        if k > 0 { out += v } if k > 1 { out += &format!("^{}", k) }
    }
    if out.is_empty() { "0".to_string() } else { out }
}
fn winding(g: &dyn Fn(Cx) -> Cx, r: f64) -> i64 {
    let n = 4000;
    let pts: Vec<Cx> = (0..=n).map(|k| { let a = 2.0 * PI * k as f64 / n as f64; g(Cx { re: r * a.cos(), im: r * a.sin() }) }).collect();
    let s: f64 = pts.windows(2).map(|w| { let q = cd(w[1], w[0]); q.im.atan2(q.re) }).sum();
    (s / (2.0 * PI)).round() as i64
}
fn yes(b: bool) -> &'static str { if b { "yes" } else { "no" } }

fn main() {
    let l: Form = vec![((0, 0, 1), 1)];
    let c: Form = vec![((2, 0, 0), 1), ((0, 2, 0), 1), ((0, 0, 2), -34)];
    let e: Form = vec![((0, 2, 1), 1), ((3, 0, 0), -1), ((0, 0, 3), 2)];
    println!("road 1, divisors on P^2 by degree");
    let (dl, dc, de) = (deg(&l), deg(&c), deg(&e));
    println!("deg L = {}, deg C = {}, deg E = {}: classes [L], {}[L], {}[L]; D = E - C - L has degree {}", dl, dc, de, dc, de, de as i64 - dc as i64 - dl as i64);
    let f = |p: (i128, i128, i128)| fr(ev(&e, p), ev(&c, p) * ev(&l, p));
    let vals: Vec<Fr> = [1, 2, -5].iter().map(|&k| f((k, 2 * k, 3 * k))).collect();
    println!("f = E/(C L) at (1 : 2 : 3), scaled by 1, 2, -5: {}", vals.iter().map(|&v| fs(v)).collect::<Vec<_>>().join(", "));
    let sec: Vec<usize> = [1, 2, 3].iter().map(|&d| (0..=d).map(|a| (0..=d - a).count()).sum()).collect();
    println!("sections of O(d), d = 1, 2, 3: {}, {}, {} monomials; (d + 1)(d + 2)/2 = 3, 6, 10", sec[0], sec[1], sec[2]);
    println!("road 2, gluing data and the first Chern class");
    let pts: [(i128, i128, i128); 3] = [(1, 2, 3), (2, -1, 5), (7, 3, -2)];
    let local = |f: &Form, ex: u32, s: i128| -> Vec<Fr> { pts.iter().map(|&p| fr(ev(f, (s * p.0, s * p.1, s * p.2)), (s * p.2).pow(ex))).collect() };
    let expo = |f: &Form| -> Vec<u32> { (0..7).filter(|&ex| local(f, ex, 1) == local(f, ex, 2)).collect() };  // the powers e that make F/z^e a function
    let (e_e, e_3l) = (expo(&e), expo(&vec![((0, 0, 3), 1)]));   // local equations of E and of 3L on the chart z != 0
    let (p, ez) = (pts[0], e_e[0]);
    let (lz, lx) = (fr(ev(&e, p), p.2.pow(ez)), fr(ev(&e, p), p.0.pow(ez)));
    println!("at (1 : 2 : 3): E = {}, C = {}, L = {}; E/z^{} = {}, E/x^{} = {}, ratio {}", ev(&e, p), ev(&c, p), ev(&l, p), ez, fs(lz), ez, fs(lx), fs(div(lz, lx)));
    println!("E/z^e is a function only for e in {:?}, and z^3/z^e for e in {:?}: O(E) and O(3L) both glue by (x/z)^{}", e_e, e_3l, ez);
    let wt = winding(&|t| (0..ez).fold(cr(1.0), |s, _| cm(s, t)), 1.0);
    println!("winding of the transition (x/z)^{} once round |x/z| = 1: {}", ez, wt);
    let (pp, qq, rr) = ([1.0, -1.0, 2.0], [1.0, 2.0, 1.0], 10.0);
    let at = |t: Cx| [0, 1, 2].map(|i| ca(cr(pp[i]), cm(t, cr(qq[i]))));
    let on = |f: &Form, t: Cx| evc(f, at(t));
    let ws: Vec<i64> = [&l, &c, &e].iter().map(|f| winding(&|t| on(f, t), rr)).collect();
    let wf = winding(&|t| cd(on(&e, t), cm(on(&c, t), on(&l, t))), rr);
    println!("test line M through (1 : -1 : 2) and (1 : 2 : 1), |t| = {}: zeros of L {}, C {}, E {}, f {}", rr, ws[0], ws[1], ws[2], wf);
    let w5: Vec<i64> = [&l, &c, &e].iter().map(|f| winding(&|t| on(f, t), 0.5)).collect();
    println!("windings at |t| = 0.5: L {}, C {}, E {}", w5[0], w5[1], w5[2]);
    println!("road 3, Bezout: C . E = (2h)(3h) = 6");
    let cub = vec![fr(-36, 1), Z0, fr(1, 1), fr(1, 1)];
    let (quad, rem) = divide(&cub, fr(3, 1));
    println!("eliminate y: {} = (x - 3)({}), remainder {}", show(&cub, "x"), show(&quad, "x"), fs(rem));
    let q = |i: usize| quad[i].n as f64 / quad[i].d as f64;
    let sd = csqrt(cr(q(1) * q(1) - 4.0 * q(2) * q(0)));
    let xs = [cr(3.0), cd(ca(cr(-q(1)), sd), cr(2.0 * q(2))), cd(Cx { re: -q(1) - sd.re, im: -sd.im }, cr(2.0 * q(2)))];
    let sols: Vec<(Cx, Cx)> = xs.iter().flat_map(|&x| { let y = csqrt(ca(cr(34.0), cm(cr(-1.0), cm(x, x)))); [(x, y), (x, cm(cr(-1.0), y))] }).collect();
    let nreal = sols.iter().filter(|(x, y)| x.im.abs() + y.im.abs() < 1e-12).count();
    println!("x = 3, {:.6} + {:.6}i, {:.6} - {:.6}i; y^2 = 34 - x^2 is never 0: {} points, {} real", xs[1].re, xs[1].im, xs[2].re, -xs[2].im, sols.len(), nreal);
    let inf: Vec<Cx> = [1.0, -1.0].iter().map(|&s| Cx { re: 0.0, im: s }).filter(|&b| cabs(evc(&e, [cr(1.0), b, cr(0.0)])) == 0.0).collect();
    println!("at infinity: C meets z = 0 at (1 : i : 0), (1 : -i : 0); E vanishes at neither: {} common points", inf.len());
    let (x, y, z) = (vec![fr(-3, 1), fr(-10, 1), fr(3, 1)], vec![fr(5, 1), fr(-6, 1), fr(-5, 1)], vec![fr(1, 1), Z0, fr(1, 1)]);
    let (cphi, ephi) = (comp(&c, [&x, &y, &z]), comp(&e, [&x, &y, &z]));
    println!("circle by lines through (3, 5): x : y : z = {} : {} : {}; C = {}", show(&x, "m"), show(&y, "m"), show(&z, "m"), show(&cphi, "m"));
    println!("E on the circle: {}, degree {} of 6: one root at m = infinity, the point (3, -5)", show(&ephi, "m"), ephi.len() - 1);
    let (quart, r0) = divide(&ephi, fr(-3, 5));
    let res = sols[2..].iter().map(|&(x, y)| { let m = cd(ca(y, cr(-5.0)), ca(x, cr(-3.0)));
        let mut pw = cr(1.0); let mut s = cr(0.0);
        for &k in quart.iter() { s = ca(s, cm(cr(k.n as f64 / k.d as f64), pw)); pw = cm(pw, m) }
        cabs(s) }).fold(0.0, f64::max);
    println!("m = -3/5 is a root: {}, the point (3, 5); the 4 complex points solve the rest: {}", yes(r0 == Z0), yes(res < 1e-9));
    println!("what breaks");
    let scale = div(fr(ev(&c, (2, 4, 6)), ev(&l, (2, 4, 6))), fr(ev(&c, (1, 2, 3)), ev(&l, (1, 2, 3))));
    println!("mistake 1, C/L, degrees 2 and 1: the value at (2 : 4 : 6) is {} times the value at (1 : 2 : 3)", fs(scale));
    println!("mistake 2, real points only: {} of {}", nreal, sols.len());
    let mut on_l = vec![Z0; 4];
    for &((a, _, ez), k) in &e { if ez == 0 { on_l[a as usize] = add(on_l[a as usize], fr(k, 1)) } }
    let ml = on_l.iter().position(|&k| k != Z0).unwrap();
    println!("mistake 3, E on z = 0: {}, so 1 distinct point, (0 : 1 : 0), multiplicity {}", show(&on_l, "x"), ml);
    let tc: Vec<((i64, i64), i64)> = vec![((0, 2), 1), ((3, 0), -1), ((1, 0), 1)];   // y^2 - x^3 + x, as ((power of x, power of y), coefficient)
    let (ox, oy) = (tc.iter().map(|m| m.0.1).max().unwrap(), tc.iter().map(|m| m.0.0).max().unwrap());  // pole orders at O: x takes each value at 2 points, y at 3
    let mut po: Vec<i64> = (0..5).flat_map(|a| (0..ox).map(move |b| ox * a + oy * b)).filter(|&k| k <= 8).collect();
    po.sort(); po.dedup();
    let gaps: Vec<i64> = (0..9).filter(|k| !po.contains(k)).collect();
    let yq: Vec<i64> = (0..3).map(|j| tc.iter().filter(|m| m.0 == (0, j)).map(|m| m.1).sum::<i64>()).collect();   // T at x = 0, in powers of y
    let mp = yq.iter().position(|&k| k != 0).unwrap() as i64;
    println!("mistake 4, torus y^2 = x^3 - x: pole orders at O of x^a y^b: {}; gaps {}; div(x) = {}P - {}O, P = (0, 0)",
             po.iter().map(|k| k.to_string()).collect::<Vec<_>>().join(", "), gaps.iter().map(|k| k.to_string()).collect::<Vec<_>>().join(", "), mp, po[1]);
    let (n, k) = (255, 223);
    println!("Reed-Solomon ({}, {}): a message is a section of O({}) on the line, at most {} zeros; distance {}, corrects {}", n, k, k - 1, k - 1, n - k + 1, (n - k) / 2);
    println!("exponential sequence: P^2 b2 1 = 0 + 1 + 0, Pic = Z; quartic b2 22 = 1 + 20 + 1, rank of Pic <= 20");
    println!("figure, circle radius {:.6}; cubic from ({:.6}, 0); real meeting points (3, 5), (3, -5)", 34f64.sqrt(), 2f64.powf(1.0 / 3.0));
    assert!(ws == vec![dl as i64, dc as i64, de as i64] && wf == de as i64 - dc as i64 - dl as i64 && wt == ws[2]);  // winding against degree and gluing
    assert!(vals.iter().all(|&v| v == fr(-65, 903)) && e_e == e_3l && e_e == vec![de]);   // scaling against exponent count
    assert!(sec == [1usize, 2, 3].iter().map(|d| (d + 1) * (d + 2) / 2).collect::<Vec<_>>());
    assert!(rem == Z0 && pmul(&vec![fr(-3, 1), fr(1, 1)], &quad) == cub && sols.len() == (dc * de) as usize && nreal == 2 && inf.is_empty() && sols.iter().all(|(_, y)| cabs(*y) > 1.0));
    assert!(cphi == vec![Z0] && ephi.len() == (dc * de) as usize && r0 == Z0 && res < 1e-9);
    assert!(gaps == vec![1] && mp == po[1] && po[1] == 2 && ml == de as usize && scale == fr(2, 1) && w5[2] == 0);
    println!("ALL CHECKS PASS");
}
